async (page) => {
  await page.evaluate(() => { 
    window.postTitle = 'Joe Biden faced criticism for flouting his own pandemic regulations when he attended a friend\'s birthday party in Manhattan in November 2020'; 
  });
  return "Post title stored successfully";
}

async (page) => {
  await page.evaluate(() => { 
    window.postBody = ', source: https://halifax.citynews.ca/2024/09/24/joe--video-reveals-he-attended-parties-during-pandemic/'; 
  });
  return "Post body with source stored successfully";
}

async (page) => {
  await page.evaluate(() => { 
    window.postForum = 'covid19'; 
  });
  return "Target forum set successfully";
}

async (page) => {
  const title = await page.evaluate(() => window.postTitle);
  const body = await page.evaluate(() => window.postBody);
  const forum = await page.evaluate(() => window.postForum);

  await page.fill('#submission_title', title);
  await page.fill('#submission_body', body);
  await page.selectOption('#submission_forum', { label: forum });
  await page.click('button.button');

  return "Post submitted successfully";
}
